```rust
// NaN identity: CPython's list/set/dict equality and membership compare each element with `is` first, which
// the typed build's unboxed floats cannot do; a comparison that reaches a NaN stops the run (AX_DYN re-runs
// it on the dynamic build) rather than giving a wrong answer.
pub trait AxNaN {
    fn ax_has_nan(&self) -> bool;
}
pub fn ax_nan_pair<T: AxNaN>(a: &T, b: &T) {
    if a.ax_has_nan() || b.ax_has_nan() {
        panic!("AX_DYN: NaN identity");
    }
}
pub fn ax_eq<T: AxNaN + PartialEq>(a: &T, b: &T) -> bool {
    ax_nan_pair(a, b);
    a == b
}
```

