// ---- NaN identity stops (typed build) ----
// CPython's list/tuple/set/dict equality, membership, index, count and remove compare each candidate with
// `is` before `==`. The typed build's unboxed f64 has no identity, so an operation whose value may be NaN
// (or hold one) stops the run instead of guessing: "AX_DYN: NaN identity" makes brevi re-run the program on
// the dynamic build (src/dynpy), whose NaN objects carry their identity in their payload.
pub trait AxNaN {
    fn ax_has_nan(&self) -> bool;
}
impl AxNaN for f64 { #[inline] fn ax_has_nan(&self) -> bool { self.is_nan() } }
impl AxNaN for Json { fn ax_has_nan(&self) -> bool { match self { Json::Num { v, .. } => v.is_nan(), Json::Arr { v } | Json::Tup { v } => v.iter().any(|x| x.ax_has_nan()), Json::Obj { v } => v.values().any(|x| x.ax_has_nan()), _ => false } } }
impl<T: AxNaN> AxNaN for Vec<T> { ... }
impl<T: AxNaN> AxNaN for AxSet<T> { ... }
impl<T: AxNaN> AxNaN for AxQueue<T> { ... }
impl<K: AxNaN, V: AxNaN> AxNaN for AxM<K, V> { ... }
impl<T: AxNaN + 'static> AxNaN for AxRow<T> { fn ax_has_nan(&self) -> bool { if self.0.is_null() { false } else { (**self).ax_has_nan() } } }
// tuples:
impl<A: AxNaN> AxNaN for (A,) { ... }
impl<A: AxNaN, B: AxNaN> AxNaN for (A, B) { ... }
... up to 8.
