#[inline]
pub fn ax_nan_stop<T: AxNaN>(x: &T) { if x.ax_has_nan() { ax_nan_panic() } }
#[inline]
pub fn ax_eq<T: AxNaN + PartialEq>(a: &T, b: &T) -> bool { ax_nan_stop(a); ax_nan_stop(b); a == b }
