        match self {
            Json::Num { v, .. } => v.is_nan(),
            Json::Arr { v } | Json::Tup { v } => v.iter().any(|x| x.ax_has_nan()),
            Json::Obj { v } => v.values().any(|x| x.ax_has_nan()),
            _ => false,
