fn kill(&mut self, p: &Pl) {
    self.st.retain(|(a, _, b, _)| a != p && b != p);
    // A rebinding (or del) cuts the name's connection to the caller's object: later changes through
    // the rebound name are Python's new local, not a change of the argument.
    self.conn.remove(p);
}

