match place {
    Some((r, d)) if eligible && !matches!(r, Pl::Ext) => {
        // passed `&mut place`: the change is the caller's own; the typed build must borrow.
        // A change of a scalar (a string an unknown call might touch, say) is invisible to
        // the caller, so only a place that may hold a container at that depth needs the borrow.
        let vis = *m >= UNK || self.kind_pl(&r) > add_d(d, *m);
        let needed = vis && (self.is_live(&r) || self.partners(&r).iter().any(|(q, _, _)| self.is_live(q)) || !matches!(r, Pl::L(_)));
        if needed {
            let tp = if fi.class.is_some() && Some(pn) == fi.params.first() { "self_".to_string() } else { pn.clone() };
            self.req_muts.insert((typed.clone(), tp));
        }
        if vis {
            self.mutate_place(&r, add_d(d, *m), &format!("by {}()", fi.def.name), false);
        }
    }

